import{_ as e,c as l,o as i,ah as c}from"./chunks/framework.BkHe6ehV.js";const u=JSON.parse('{"title":"AllenAI Olmo 系列","description":"","frontmatter":{"title":"AllenAI Olmo 系列","date":"2026-09-23 12:00:00","create":"2026-09-23 12:00:00","categories":["mainllm"],"tags":["基模","Pretrain","SFT","RL"],"readingStats":{"words":3312,"minutes":10,"images":0}},"headers":[],"relativePath":"posts/llm/industry/mainllm/22-olmo-series.md","filePath":"posts/llm/industry/mainllm/22-olmo-series.md","lastUpdated":null}'),t={name:"posts/llm/industry/mainllm/22-olmo-series.md"};function d(s,o,n,r,a,g){return i(),l("div",null,o[0]||(o[0]=[c('<h2 id="变化点" tabindex="-1">变化点 <a class="header-anchor" href="#变化点" aria-label="Permalink to &quot;变化点&quot;">​</a></h2><div class="custom-block info"><div class="custom-block-title">2025</div><p><strong>2025.12 · <a href="#_2512-olmo-3-开放训练流程、delta-learning、olmorl">Olmo 3</a></strong></p><ul><li>公开预训练、长上下文扩展、SFT、DPO 与推理 RL 的数据和中间检查点。</li><li>Think 采用 SFT → Delta Learning DPO → OlmoRL，并对比 Instruct 与 RL-Zero 路线。</li></ul></div><h2 id="_2512-olmo-3-开放训练流程、delta-learning、olmorl" tabindex="-1">(2512) Olmo 3 (开放训练流程、Delta Learning、OlmoRL) <a class="header-anchor" href="#_2512-olmo-3-开放训练流程、delta-learning、olmorl" aria-label="Permalink to &quot;(2512) Olmo 3 (开放训练流程、Delta Learning、OlmoRL)&quot;">​</a></h2><p>🌺 <strong>论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">Olmo 3 论文摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://www.alphaxiv.org/abs/2512.13961" target="_blank" rel="noreferrer">paper</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>仅开放最终权重，难以研究训练数据、基础能力和 RL 之间的关系；需要可重建各阶段的模型与数据流程。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>架构与预训练</strong>：7B / 32B Dense 模型采用 <code>3:1</code> 局部/全局 Attention；用 Token 预算约束的数据混合与质量感知上采样训练 Dolma 3 语料。</li><li><strong>中训练与长上下文</strong>：<code>100B</code> 高质量 Dolmino 数据增强数学、代码和后训练基础，再用 Longmino 混合长短文本将上下文从 <code>8K</code> 扩至 <code>65K</code>。</li><li><strong>Think 后训练</strong>：约 <code>2.25M</code> 条 SFT 数据、<code>200K</code> 对高能力差异的偏好数据，再用数学、代码、指令与聊天组成的 OlmoRL 训练。</li><li><strong>Instruct / RL-Zero</strong>：Instruct 从 Think SFT 起步，加入工具轨迹并控制偏好对的长度差；RL-Zero 从 Base 直接训练，并清除 RL 数据与前期训练语料的重叠。</li></ul><p><strong>模型效果(Olmo 3 Think 32B + SFT/DPO/OlmoRL)</strong></p><ul><li>SFT → DPO → 初版 RL：AIME 2025 <code>66.2 → 70.7 → 72.5</code>，LiveCodeBench v3 <code>75.8 → 81.9 → 83.5</code>。</li><li>同报告的延长 RL 版本 Olmo 3.1 Think 32B，AIME 2025 达到 <code>78.1</code>、IFBench 达到 <code>68.1</code>。</li></ul><p><strong>重要结论</strong></p><ul><li><strong>偏好差异比单独模仿更有效</strong>：7B 开发实验中，继续 SFT 强模型回答使均分 <code>70.3 → 64.5</code>；将它与弱模型回答配对做 DPO，均分达到 <code>72.9</code>。</li><li><strong>中训练可提前放入推理与指令数据</strong>：固定 <code>100B</code> Token 的对照中，加入后 OlmoBaseEval 均分 <code>48.8 → 50.7</code>。</li></ul><p><strong>关键贡献</strong></p><ul><li>提供完整 Model Flow、Dolma / Dolci 数据家族、OlmoBaseEval 与 OlmoRL，使预训练到 RL 的因果分析有公开起点。</li></ul><p><strong>未来方向</strong></p><ul><li>研究多目标 RL 的领域相互作用、后训练超参数选择，以及更长 RL 训练和更高效的 Learner 配置。</li></ul></div><h3 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">研究训练过程需要中间产物</div><ul><li><strong>数据贡献难以定位</strong>：最终权重无法揭示哪些能力来自预训练、中训练、蒸馏或 RL。</li><li><strong>不同使用目标需要不同分支</strong>：长推理模型、简洁交互模型和直接从 Base 开始的 RL 实验，其数据与模板不相同。</li><li><strong>小规模试验需要可靠评测</strong>：不同任务对模型大小、数据与采样噪声的响应不同，单一总分可能掩盖退化。</li><li><strong>开放范围</strong>：发布数据、处理代码、训练代码、日志和阶段检查点，并记录模型之间的训练与合并关系。</li></ul></div><h3 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="dense-架构与-dolma-3-预训练" tabindex="-1">Dense 架构与 Dolma 3 预训练 <a class="header-anchor" href="#dense-架构与-dolma-3-预训练" aria-label="Permalink to &quot;Dense 架构与 Dolma 3 预训练&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">7B / 32B 网络与训练预算</div><ul><li><strong>网络</strong>：分别为 <code>32 / 64</code> 层、隐藏维度 <code>4096 / 5120</code>，使用 SwiGLU、RMSNorm 与 QK-Norm。</li><li><strong>Attention</strong>：7B 为 <code>32</code> 个 Query / KV Heads 的 MHA；32B 为 <code>40</code> 个 Query Heads、<code>8</code> 个 KV Heads 的 GQA。</li><li><strong>局部/全局布局</strong>：每四层中三层采用 <code>4096</code> Token 窗口，一层使用全局 Attention，最后一层保持全局。</li><li><strong>预训练上下文</strong>：<code>8192</code>；7B 训练 <code>5.93T tokens</code>，32B 的原定余弦计划在 <code>5.5T tokens</code> 处结束，进入中训练。</li><li><strong>计算精度与实现</strong>：BF16 训练，OLMo-core 结合编译、自定义 Attention / LM Head 算子、异步指标与检查点写入。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">数据比例与质量共同优化</div><p><strong>Dolma 3 Mix</strong></p><ul><li>从约 <code>9.31T</code> Token 池形成约 <code>5.93T</code> 的训练混合：Common Crawl <code>76.1%</code>、olmOCR 科学 PDF <code>13.6%</code>、Stack-Edu 代码 <code>6.89%</code>、FineMath <code>2.56%</code>，其余为 arXiv 与百科数据。</li><li>Web 数据经过清洗、质量筛选和全局去重；科学 PDF 由 olmOCR 线性化为可训练文本。</li></ul><p><strong>Token 约束混合</strong></p><ul><li>训练一组 <code>30M</code> 参数代理模型，每个训练 <code>3B tokens</code>；从以自然分布为中心的 Dirichlet 分布采样数据比例。</li><li>为每项 Base Easy 任务拟合“混合比例 → Bits-per-Byte”回归模型，再搜索平均 BPB 最低的比例。</li><li>搜索同时约束总 Token 预算和各领域重复次数上限，通常不超过约 <code>4～7</code> 次。</li><li>新领域加入时，将已有最优混合冻结为一个虚拟领域，仅重做它与新增领域的混合，减少重新搜索成本。</li></ul><p><strong>质量感知上采样</strong></p><ul><li>在每个 Web 主题内部，按质量分位设计采样曲线，让高质量数据重复更多次。</li><li>曲线积分满足该主题的目标 Token 数，同时受最大重复次数限制；跨领域比例与领域内部质量选择共同决定最终数据。</li></ul></div><h4 id="dolmino-中训练与-longmino-上下文扩展" tabindex="-1">Dolmino 中训练与 Longmino 上下文扩展 <a class="header-anchor" href="#dolmino-中训练与-longmino-上下文扩展" aria-label="Permalink to &quot;Dolmino 中训练与 Longmino 上下文扩展&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">100B 中训练：兼顾基础分数与后训练能力</div><ul><li><strong>数据池与预算</strong>：从 <code>2.19T</code> Token 池采样约 <code>100B</code>；混合数学、代码、QA、推理轨迹、指令与高质量自然文本。</li><li><strong>代码数据</strong>：<code>10B</code> Stack-Edu FIM 与 <code>10B</code> CraneCode；数学包含 Dolmino Math、CraneMath、TinyMATH 等。</li><li><strong>QA 与推理</strong>：Reddit 转 Flashcards、Wikipedia 转阅读理解问答，加入 Meta-Reasoning、程序可验证推理和多个开放推理数据集。</li><li><strong>格式处理</strong>：中训练中的指令数据去掉特殊 Chat Tokens 与模板，保留普通换行组织；正式对话格式留给 SFT 学习。</li><li><strong>32B 合并</strong>：用不同数据顺序分别跑两次 <code>100B</code> 中训练，再平均两支检查点权重；两次是独立分支。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">从 8192 扩展到 65536</div><ul><li><strong>Longmino 数据</strong>：约 <code>639B</code> Token 的长文本池，以科学 PDF 为主；添加跨段词频统计 <code>CWE</code> 与跨片段表达改写 <code>REX</code>，增强聚合信息的训练信号。</li><li><strong>最终配比</strong>：约 <code>34%</code> 长文本与 <code>66%</code> 中训练短文本混合；7B 训练 <code>50B</code>、32B 训练 <code>100B tokens</code>。</li><li><strong>位置编码</strong>：仅在全局 Attention 层应用 YaRN，局部层保持原位置设置。</li><li><strong>打包与掩码</strong>：Best-Fit Packing 减少长文被切断；Intra-Document Masking 禁止无关文档之间互相注意。</li><li><strong>系统实现</strong>：<code>8-way Context Parallelism</code> 将每个 <code>65K</code> 序列分到八张卡；32B 最后平均长上下文阶段的三个检查点。</li></ul></div><h4 id="think-sft、delta-learning-与-olmorl" tabindex="-1">Think：SFT、Delta Learning 与 OlmoRL <a class="header-anchor" href="#think-sft、delta-learning-与-olmorl" aria-label="Permalink to &quot;Think：SFT、Delta Learning 与 OlmoRL&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">先学习完整推理，再学习回答之间的能力差异</div><p><strong>Dolci Think SFT</strong></p><ul><li>7B / 32B 分别使用约 <code>2.268M / 2.254M</code> 条样本，覆盖数学、代码、指令、聊天、安全、科学和多语言。</li><li>数学与代码主要使用 QwQ-32B 等开放轨迹；不完整推理重新生成到最多 <code>32K</code>，仍不完整则丢弃。</li><li>代码通过执行测试筛选，精确指令通过约束验证器筛选；聊天、安全等来源由 DeepSeek R1 生成推理回答。</li><li>清理重复、模型身份和无关任务，并去除评测重叠；训练 <code>2 epochs</code>，最后合并两个不同学习率的 SFT 检查点。</li></ul><p><strong>Delta Learning DPO</strong></p><ul><li>对同一 Prompt，选择 Qwen3 32B Thinking 的回答作为 Chosen，Qwen3 0.6B Thinking 的回答作为 Rejected，形成 <code>200K</code> 对偏好数据。</li><li>过滤 Chosen 的无关内容与身份信息，保留 Rejected 中的错误以提供有用差异；不要求 Chosen 本身一定强到值得继续模仿。</li><li>用 DPO 提高 Chosen 相对 Rejected 的概率；训练 <code>1 epoch</code>，搜索学习率与数据规模，避免更多偏好数据造成退化。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">OlmoRL：多领域奖励与 GRPO 修改</div><p><strong>数据和奖励</strong></p><ul><li>Think RL 共 <code>104869</code> 个 Prompt：数学、代码、精确指令和一般聊天；7B 离线每题采样 <code>8</code> 次，去掉通过率超过 <code>62.5%</code> 的过易题。</li><li>数学用规范化答案与 SymPy 验证；代码运行测试，比较全通过二值奖励与通过比例奖励；指令检查是否满足全部约束。</li><li>一般聊天由 Qwen3 32B 非 Thinking Judge 给出 <code>[0,1]</code> 分，可使用参考答案，也可直接评价开放回答。</li><li>代码合成流程为问题改写、解答生成、测试生成；保留参考解答通过率高于 <code>80%</code> 的问题，并去掉失败测试。</li></ul><p><strong>训练目标</strong></p><ul><li>优势为 <code>r_i − mean_group(r)</code>，不做组内标准差归一化；按 Batch 总 Token 数归一化损失，去掉 KL。</li><li>过滤全组相同奖励的零梯度样本；Active Sampling 持续补样本，直到凑齐所需有效 Batch。</li><li>非对称裁剪采用 <code>ε_low=0.2</code>、<code>ε_high=0.272</code>；每题采样 <code>8</code> 条，温度 <code>1.0</code>。</li><li>新版实现使用截断重要性采样，修正训练引擎和 vLLM 的 Token 概率差异；32B 配置的比率上限为 <code>2.0</code>。</li><li>Think 的回答上限为 <code>32768</code>；初版 32B 训练 <code>750 steps</code>，同报告的 Olmo 3.1 Think 延长至 <code>2300 steps</code>。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">连续生成与生成中更新权重</div><ul><li><strong>异步 Learner / Actor</strong>：中心 Learner 更新参数，多组 vLLM Actor 持续生成，结果通过队列送回。</li><li><strong>Continuous Batching</strong>：某个回答结束后立即填入新请求，避免短回答等待最长回答；论文实例平均长度 <code>14628</code>、上限 <code>32K</code>，静态组批可浪费约 <code>54%</code> 计算。</li><li><strong>Inflight Updates</strong>：无需等待所有回答结束即可更新 Actor 权重，正在生成的回答继续复用原 KV Cache。</li><li><strong>版本差异</strong>：初版 7B Think RL 未使用后来的 PipelineRL 与截断重要性采样；新版实现复现实验达到接近质量，训练时间由约 <code>15</code> 天缩至 <code>6</code> 天。</li></ul></div><h4 id="instruct-与-rl-zero-分支" tabindex="-1">Instruct 与 RL-Zero 分支 <a class="header-anchor" href="#instruct-与-rl-zero-分支" aria-label="Permalink to &quot;Instruct 与 RL-Zero 分支&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">简洁交互与可控研究分别训练</div><p><strong>Olmo 3 Instruct</strong></p><ul><li>从 Think SFT 模型继续训练，使用约 <code>2.152M</code> 条 Instruct SFT 数据，其中工具数据约 <code>228K</code> 条。</li><li>工具数据包含真实 MCP 环境交互和合成函数调用，覆盖科学检索、网页搜索等；非推理回答移除思考轨迹和特殊 Token。</li><li>DPO 结合非 Thinking 强弱模型回答、GPT Judge 偏好和多轮偏好；多轮对只改变最后一轮，避免不同历史导致比较含混。</li><li>在聊天与多轮偏好子集中，将 Chosen / Rejected 长度差限制为 <code>100 tokens</code>，缓解偏好训练学到的冗长倾向。</li><li>后续用 OlmoRL 训练，7B / 32B 回答上限分别为 <code>8K / 16K</code>；使用较容易的数学、代码数据，并跳过 Think 分支的离线难度筛选。</li></ul><p><strong>Olmo 3 RL-Zero</strong></p><ul><li>从 Base 直接进行数学、代码、精确指令、聊天或混合领域 RL，发布独立数据和检查点供受控比较。</li><li>数学数据经语义聚类、去重及与预训练/中训练/评测去重，再去掉起点模型 <code>8/8</code> 全部答对的问题，保留约 <code>13.3K</code> 个 Prompt。</li><li>使用与 Base 相容的简单文本模板；训练回答上限 <code>16K</code>，评测上限 <code>32K</code>、温度 <code>1.0</code>，同时观察 pass@1 和 pass@k。</li></ul></div><h3 id="实验设置" tabindex="-1">实验设置 <a class="header-anchor" href="#实验设置" aria-label="Permalink to &quot;实验设置&quot;">​</a></h3><div class="custom-block info"><div class="custom-block-title">按阶段评测与比较</div><ul><li><strong>Base</strong>：OlmoBaseEval 共 <code>43</code> 项任务，分小模型开发用的 Easy 与最终模型用的 Main；另保留 MMLU Pro、DeepMind Math、LBPP、BBH 四个未用于发布前开发的测试集。</li><li><strong>Think / Instruct</strong>：数学、推理、代码、指令、知识问答与聊天；主表统一 <code>32K</code> 上下文上限、温度 <code>0.6</code>、Top-p <code>0.95</code>。</li><li><strong>降低采样方差</strong>：AIME 使用多次采样平均、LiveCodeBench 使用 Avg@10；主比较与开发消融分别标明，不把单次开发均分当最终模型成绩。</li><li><strong>工具评测</strong>：BFCLv3，以及基于 MCP 的 LitQA2 / SimpleQA；温度 <code>0</code>、最多 <code>10</code> 轮，运行三次取均值。</li><li><strong>版本范围</strong>：本地报告包含 Olmo 3.1 的延长训练结果，下面与初版 Olmo 3 分开列出。</li></ul></div><h3 id="关键结果-olmo-3-think-32b-sft-dpo-olmorl" tabindex="-1">关键结果(Olmo 3 Think 32B + SFT/DPO/OlmoRL) <a class="header-anchor" href="#关键结果-olmo-3-think-32b-sft-dpo-olmorl" aria-label="Permalink to &quot;关键结果(Olmo 3 Think 32B + SFT/DPO/OlmoRL)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">各阶段收益与延长 RL</div><p><strong>32B：SFT → DPO → 初版 Olmo 3 Think</strong></p><ul><li>AIME 2024：<code>73.5 → 76.0 → 76.8</code>；AIME 2025：<code>66.2 → 70.7 → 72.5</code>。</li><li>LiveCodeBench v3：<code>75.8 → 81.9 → 83.5</code>；IFBench：<code>37.0 → 34.4 → 47.6</code>。</li><li>DPO 与 RL 改善的领域不同；例如 DPO 后 IFEval 从 <code>83.9</code> 降至 <code>80.6</code>，RL 后提高到 <code>89.0</code>。</li></ul><p><strong>32B：初版 RL → Olmo 3.1 延长 RL</strong></p><ul><li><code>750 → 2300 steps</code> 后，AIME 2025 <code>72.5 → 78.1</code>，IFBench <code>47.6 → 68.1</code>。</li><li>LiveCodeBench v3 基本不变：<code>83.5 → 83.3</code>；AlpacaEval 2 LC 从 <code>74.2 → 69.1</code>，延长 RL 并非所有能力都同步提高。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">训练数据和偏好机制消融</div><ul><li><strong>中训练提前加入推理与指令有效</strong>：固定 <code>100B tokens</code> 的中间混合对照中，Base 均分 <code>48.8 → 50.7</code>，数学 <code>43.1 → 48.7</code>、代码 <code>23.3 → 24.4</code>。</li><li><strong>Chosen 未必适合直接 SFT</strong>：7B 开发检查点均分 <code>70.3</code>；继续模仿 Qwen3 32B Chosen 后降至 <code>64.5</code>，与 0.6B Rejected 配对 DPO 后提高到 <code>72.9</code>。</li><li><strong>DPO 可改善 RL 起点</strong>：另一组 7B 单次评测、同为 <code>1000 RL steps</code> 的比较中，SFT+RL 均分 <code>71.9</code>，SFT+DPO+RL 为 <code>74.1</code>；两者分别用各自起点筛选 RL 数据。</li><li><strong>短文本混合保护基础能力</strong>：<code>10B</code> Token 上下文扩展消融中，长/短 <code>66/34</code> 使基础任务均分降低 <code>2.5pt</code>，调整为 <code>34/66</code> 后只降 <code>0.8pt</code>。</li><li><strong>Think SFT 可作为 Instruct 起点</strong>：7B 中间检查点对照均分 <code>44.5 → 47.8</code>，MATH <code>60.3 → 65.9</code>；最终输出仍保持简洁。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">RL 系统与研究用途</div><ul><li>同一系统消融依次加入连续组批、线程优化、生成中更新后，吞吐为 <code>881 → 975 → 1358 → 2949 tokens/s</code>，生成中更新带来的增量最大。</li><li>RL-Zero 的数学训练同时改善 pass@1 与 pass@32，可用于观察 RL 对解题覆盖范围的影响。</li><li>混合领域 RL 的各领域均有进步，但相较单领域训练仍不充分，说明公开混合任务可用于研究目标之间的竞争与协同。</li></ul></div><h3 id="未来方向" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block note"><div class="custom-block-title">作者提出的后续问题</div><ul><li>使用 RL-Zero 的混合任务研究多目标 RLVR 中不同领域的相互作用。</li><li>改进后训练超参数选择，降低反复搜索与长输出评测的计算成本。</li><li>延长尚未充分饱和的 RL 训练，并改善 32B Learner 的分片与利用率。</li></ul></div>',28)]))}const h=e(t,[["render",d]]);export{u as __pageData,h as default};
